"""Shared dataclasses for cvnpy."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import numpy as np


@dataclass
class ValStruct:
    """Equivalent to MATLAB valstruct with concatenated LH+RH data."""

    data: np.ndarray
    numlh: int
    numrh: int


@dataclass
class Surface:
    """Surface mesh container."""

    vertices: np.ndarray
    faces: np.ndarray
    patchmask: np.ndarray | None = None


@dataclass
class Lookup:
    """Lookup table container generated by spherelookup_* algorithms."""

    payload: dict[str, Any]
